-- Adds Oh, Yvi! to a Studio that was already seeded, or refreshes it. Safe to run again.
begin;
update public.studio_projects set position = position + 1
  where not exists (select 1 from public.studio_projects where slug = 'oh-yvi');
insert into public.studio_projects
  (slug, position, published, name, kind, category, tags, stamps, year, years, role_short, role, platform, status,
   live_url, docs_url, design_system_url, screenshots, facts, stats, entries)
values ($t$oh-yvi$t$, 0, true, $t$Oh, Yvi!$t$, $t$Stationery e-commerce store$t$, $t$E-commerce · Web design & build$t$, array[$t$web$t$]::text[], array[$t$ecommerce$t$]::text[], 2026, $t$Oct–Nov 2026$t$, $t$Co-founder, designer & builder$t$, $t$Co-founder with Loveline Loverez; designer and developer, building with Claude as an AI pair programmer$t$, $t$Web$t$, $t$live$t$, $t$https://www.ohyvi.com$t$, null, null, $j$[{"label":"Homepage","src":"/projects/oh-yvi/home.webp"},{"label":"Collections","src":"/projects/oh-yvi/collections.webp"},{"label":"Affiliate program","src":"/projects/oh-yvi/affiliate.webp"}]$j$::jsonb, $j$[{"label":"Designed in Figma, built from scratch","value":"Georgia, PT Mono and one warm brown, turned into a Next.js store."},{"label":"Its own Studio","value":"Products, orders, promos, affiliates and newsletters, managed in an admin I built instead of rented."},{"label":"Opened November 11, 2026","value":"Christmas specials and digital printables first, then new product batches through January."}]$j$::jsonb, $j$[{"value":"Nov 11","label":"opening day, 2026"},{"value":"9","label":"product batches, November to January"},{"value":"2","label":"kinds of goods, printed and digital"}]$j$::jsonb, $j$[{"stage":"overview","label":"Overview","date":"Dear diary, October 2026","body":"Loveline and I started a stationery brand in Lipa, Batangas: journals, trackers, planners and washi tape for people who like to write things down. Papered goodness. I designed the store in Figma, then built it from scratch."},{"stage":"challenge","label":"Context & challenge","date":"October 2026","body":"A tiny brand still needs a real store. Printed and digital goods, pre-orders that pay for the printing, an affiliate program and newsletters, all with a look that's ours and not a template's."},{"stage":"approach","label":"Approach","date":"Along the way","body":"One codebase on Next.js, Supabase, Resend and Vercel. The cart is a Bag, favorites are Interests, and digital goods land in a My Library page with an email as backup. Behind it, a Studio for products, collections, bundles, promos, orders, articles, affiliates and newsletters, so running the shop never needs code."},{"stage":"outcome","label":"Outcome","date":"November 2026","body":"The store opened on November 11, 2026 at ohyvi.com, with Christmas specials and digital printables first and the rest of the printed range from January."},{"stage":"reflection","label":"Reflection","date":"Looking back","body":"[Your reflection on Oh, Yvi! goes here.]"}]$j$::jsonb)
on conflict (slug) do update set
  name = excluded.name, kind = excluded.kind, category = excluded.category, tags = excluded.tags, stamps = excluded.stamps,
  year = excluded.year, years = excluded.years, role_short = excluded.role_short, role = excluded.role, platform = excluded.platform,
  status = excluded.status, live_url = excluded.live_url, docs_url = excluded.docs_url, design_system_url = excluded.design_system_url,
  screenshots = excluded.screenshots, facts = excluded.facts, stats = excluded.stats, entries = excluded.entries;
commit;
